(x, y, t) => {
  const s = [
    [120 + Math.sin(t * 0.7) * 80, 60 + Math.cos(t * 0.5) * 40],
    [360 + Math.cos(t * 0.6) * 80, 180 + Math.sin(t * 0.8) * 40],
    [240 + Math.sin(t * 0.4 + 1.5) * 120, 100 + Math.cos(t * 0.6 + 0.8) * 60],
    [80 + Math.cos(t * 0.5 + 3) * 60, 180 + Math.sin(t * 0.3 + 2) * 50],
    [400 + Math.sin(t * 0.8 + 4) * 70, 50 + Math.cos(t * 0.7 + 1) * 35]
  ];
  const fr = [0.08, 0.1, 0.065, 0.09, 0.075], sp = [2.0, 1.7, 2.3, 1.9, 2.1], am = [1.0, 0.9, 1.1, 0.8, 0.95];
  let act = 0, inh = 0;
  for (let i = 0; i < 5; i++) {
    const d = Math.sqrt((x - s[i][0]) ** 2 + (y - s[i][1]) ** 2);
    const w = Math.sin(d * fr[i] - t * sp[i]) * am[i];
    if (i < 3) act += w; else inh += w;
  }
  act /= 3; inh /= 2;
  const b1 = Math.sin(x * 0.05 + y * 0.03 + t * 0.8), b2 = Math.sin(x * 0.03 - y * 0.05 + t * 1.1);
  const b3 = Math.sin((x + y) * 0.15 + t * 3) * 0.12, b4 = Math.sin((x - y) * 0.12 - t * 2.5) * 0.12;
  const bg = (b1 + b2) / 2 + b3 + b4;
  const cx = 240, cy = 120, dist = Math.sqrt((x - cx) ** 2 + (y - cy) ** 2);
  const ang = Math.atan2(y - cy, x - cx);
  const radial = Math.sin(dist * 0.04 - t * 1.5), angular = Math.sin(ang * 6 + t * 0.4);
  const spiral = Math.sin(ang * 3 + dist * 0.02 - t * 1.2) * 0.3;
  const m1 = Math.sin(x * 0.2 + t * 2) * Math.sin(y * 0.2 - t * 1.5) * 0.15;
  const m2 = Math.sin((x * 0.15 - y * 0.1) + t * 1.8) * 0.1;
  const d01 = Math.abs(Math.sqrt((x - s[0][0]) ** 2 + (y - s[0][1]) ** 2) - Math.sqrt((x - s[1][0]) ** 2 + (y - s[1][1]) ** 2));
  const hyp = Math.sin(d01 * 0.1 - t * 1.5) * 0.3;
  const warp = Math.sin(x * 0.02 + y * 0.015 + t * 0.6) * 8;
  const dw = Math.sqrt((x - cx + warp) ** 2 + (y - cy + warp * 0.7) ** 2);
  const ring = Math.sin(dw * 0.035 - t * 1.8) * 0.2;
  const reaction = act - inh * 0.7 + bg * 0.4 + m1 + m2;
  const spot = Math.tanh(reaction * 2.5);
  const p2 = Math.tanh((radial + angular * 0.5 + spiral) * 2);
  const blend = spot * 0.45 + p2 * 0.25 + hyp * 0.15 + ring * 0.15;
  const v = blend * 0.5 + 0.5;
